from html.parser import HTMLParser
import json
class P(HTMLParser):
    def __init__(self):
        super().__init__()
        self.links=[]; self.ids=set(); self.labels=[]; self.inputs=[]; self.lang=None
    def handle_starttag(self,t,a):
        a=dict(a)
        if t=='a': self.links.append(a.get('href'))
        if 'id' in a: self.ids.add(a['id'])
        if t=='label': self.labels.append(a.get('for'))
        if t=='input': self.inputs.append(a.get('id'))
        if t=='html': self.lang=a.get('lang')
p=P();p.feed(open('index.html').read())
print(json.dumps(sorted(x for x in p.links if x and x.startswith('#') and x[1:] in p.ids)))

